-- =====================================================================
-- 0001 FOUNDATION: extensions, schemas, tenant context, organization,
-- identity & access, audit, synchronization infrastructure.
-- Conventions (apply to every table in every migration):
--   * id uuid PK (UUIDv7 generated by app/edge nodes; gen_random_uuid fallback)
--   * company_id on every tenant row  -> enforced by row level security
--   * branch_id on branch-owned rows  -> enforced by row level security
--   * created_at / updated_at / created_by / updated_by / row_version
--   * status columns are CHECK-constrained text enums
--   * money numeric(18,4), quantities numeric(18,6), rates numeric(9,6)
--   * ledgers (stock, journal, payments, loyalty, audit, order events) are append-only
-- =====================================================================
create extension if not exists citext;

create schema if not exists app;      -- helper functions
create schema if not exists org;      -- companies, branches
create schema if not exists iam;      -- users, roles, permissions, sessions
create schema if not exists audit;    -- audit log
create schema if not exists sync;     -- nodes, devices, outbox/inbox, conflicts
create schema if not exists crm;      -- customers
create schema if not exists menu;     -- menu, dishes, modifiers, pricing
create schema if not exists recipe;   -- recipes
create schema if not exists inv;      -- inventory masters, ledger, documents
create schema if not exists supl;     -- suppliers
create schema if not exists proc;     -- procurement
create schema if not exists pos;      -- orders, tables, shifts
create schema if not exists pay;      -- payments
create schema if not exists kds;      -- kitchen
create schema if not exists dlv;      -- delivery & riders
create schema if not exists agg;      -- aggregators
create schema if not exists loy;      -- loyalty
create schema if not exists mkt;      -- marketing
create schema if not exists exp;      -- expenses
create schema if not exists acct;     -- accounting & tax

-- ---------------------------------------------------------------------
-- Tenant / session context. The API sets these with SET LOCAL inside
-- every transaction; RLS policies read them.
-- ---------------------------------------------------------------------
create or replace function app.current_company_id() returns uuid
  language sql stable as $$ select nullif(current_setting('app.company_id', true), '')::uuid $$;
create or replace function app.current_branch_ids() returns uuid[]
  language sql stable as $$ select coalesce(nullif(current_setting('app.branch_ids', true), '')::uuid[], '{}'::uuid[]) $$;
create or replace function app.all_branches() returns boolean
  language sql stable as $$ select coalesce(nullif(current_setting('app.all_branches', true), '')::boolean, false) $$;
create or replace function app.is_system() returns boolean
  language sql stable as $$ select coalesce(nullif(current_setting('app.system', true), '')::boolean, false) $$;
create or replace function app.current_user_id() returns uuid
  language sql stable as $$ select nullif(current_setting('app.user_id', true), '')::uuid $$;
create or replace function app.sync_applying() returns boolean
  language sql stable as $$ select coalesce(nullif(current_setting('app.sync_applying', true), '')::boolean, false) $$;

-- touch: maintain updated_at / updated_by / row_version (optimistic concurrency + sync)
create or replace function app.touch() returns trigger language plpgsql as $$
begin
  new.updated_at := now();
  new.row_version := coalesce(old.row_version, 0) + 1;
  if app.current_user_id() is not null then new.updated_by := app.current_user_id(); end if;
  return new;
end $$;

create or replace function app.stamp_creator() returns trigger language plpgsql as $$
begin
  if new.created_by is null then new.created_by := app.current_user_id(); end if;
  return new;
end $$;

-- append-only guard for ledgers
create or replace function app.forbid_mutation() returns trigger language plpgsql as $$
begin
  raise exception '% on %.% is not allowed: table is append-only (use a reversal entry)',
    tg_op, tg_table_schema, tg_table_name using errcode = 'P0001';
end $$;

-- ---------------------------------------------------------------------
-- ORGANIZATION
-- ---------------------------------------------------------------------
create table org.companies (
  id               uuid primary key default gen_random_uuid(),
  code             citext not null unique,
  legal_name       text not null,
  trade_name       text,
  vat_registration_no text,                         -- UAE TRN (15 digits)
  base_currency    char(3) not null default 'AED',
  timezone         text not null default 'Asia/Dubai',
  country_code     char(2) not null default 'AE',
  prices_include_tax boolean not null default true,
  settings         jsonb not null default '{}'::jsonb,
  status           text not null default 'active' check (status in ('active','inactive','suspended')),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  created_by uuid, updated_by uuid, row_version bigint not null default 1,
  constraint companies_trn_chk check (vat_registration_no is null or vat_registration_no ~ '^[0-9]{15}$')
);

create table org.branches (
  id            uuid primary key default gen_random_uuid(),
  company_id    uuid not null references org.companies(id),
  code          citext not null,
  name          text not null,
  address_line  text,
  city          text,
  emirate       text,
  phone         text,
  email         citext,
  latitude      numeric(9,6),
  longitude     numeric(9,6),
  timezone      text,                               -- null = company timezone
  vat_registration_no text,                         -- null = company TRN
  business_day_cutoff time not null default '04:00',-- sales after midnight belong to previous business day
  settings      jsonb not null default '{}'::jsonb,
  status        text not null default 'active' check (status in ('active','inactive','closed')),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  created_by uuid, updated_by uuid, row_version bigint not null default 1,
  unique (company_id, code),
  unique (company_id, id)                            -- target for composite (tenant-safe) FKs
);
create index branches_company_idx on org.branches(company_id);

-- ---------------------------------------------------------------------
-- IDENTITY & ACCESS
-- ---------------------------------------------------------------------
create table iam.permissions (                      -- global catalogue, code-defined
  code        text primary key,                     -- e.g. 'pos.order.void'
  module      text not null,
  description text not null,
  is_sensitive boolean not null default false,      -- requires reason code / audit
  created_at  timestamptz not null default now()
);

create table iam.roles (
  id          uuid primary key default gen_random_uuid(),
  company_id  uuid references org.companies(id),    -- null = platform role (Super Admin)
  code        citext not null,
  name        text not null,
  description text,
  is_system   boolean not null default false,       -- seeded roles cannot be deleted
  scope       text not null default 'branch' check (scope in ('platform','company','branch')),
  status      text not null default 'active' check (status in ('active','inactive')),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  created_by uuid, updated_by uuid, row_version bigint not null default 1
);
create unique index roles_company_code_uq on iam.roles(coalesce(company_id, '00000000-0000-0000-0000-000000000000'::uuid), code);
create index roles_company_idx on iam.roles(company_id);

create table iam.role_permissions (
  id              uuid not null unique default gen_random_uuid(),
  role_id         uuid not null references iam.roles(id) on delete cascade,
  permission_code text not null references iam.permissions(code),
  company_id      uuid references org.companies(id),
  created_at      timestamptz not null default now(),
  created_by      uuid,
  primary key (role_id, permission_code)
);
create index role_permissions_perm_idx on iam.role_permissions(permission_code);

create table iam.users (
  id              uuid primary key default gen_random_uuid(),
  company_id      uuid references org.companies(id),  -- null = platform user
  email           citext not null unique,
  username        citext,
  full_name       text not null,
  mobile          text,
  password_hash   text not null,                      -- scrypt$N$r$p$salt$hash
  pin_hash        text,                               -- POS quick-login PIN (scrypt)
  must_change_password boolean not null default false,
  failed_login_count int not null default 0 check (failed_login_count >= 0),
  locked_until    timestamptz,
  last_login_at   timestamptz,
  password_changed_at timestamptz not null default now(),
  default_branch_id uuid references org.branches(id),
  locale          text not null default 'en',
  status          text not null default 'active' check (status in ('active','inactive','locked')),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  created_by uuid, updated_by uuid, row_version bigint not null default 1
);
create unique index users_company_username_uq on iam.users(company_id, username) where username is not null;
create index users_company_idx on iam.users(company_id);

-- role grant; branch_id null = all branches of the company
create table iam.user_roles (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references iam.users(id) on delete cascade,
  role_id     uuid not null references iam.roles(id),
  company_id  uuid references org.companies(id),
  branch_id   uuid references org.branches(id),
  valid_from  timestamptz not null default now(),
  valid_to    timestamptz,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  created_by uuid, updated_by uuid, row_version bigint not null default 1,
  check (valid_to is null or valid_to > valid_from),
  foreign key (company_id, branch_id) references org.branches(company_id, id)   -- branch must belong to the grant's company
);
create unique index user_roles_uq on iam.user_roles(user_id, role_id, coalesce(branch_id, '00000000-0000-0000-0000-000000000000'::uuid));
create index user_roles_company_idx on iam.user_roles(company_id);
create index user_roles_branch_idx on iam.user_roles(branch_id);

create table iam.sessions (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid not null references iam.users(id) on delete cascade,
  company_id     uuid references org.companies(id),
  token_hash     bytea not null unique,                -- sha256 of bearer token; raw token never stored
  device_id      uuid,                                 -- FK added after sync.devices
  ip_address     inet,
  user_agent     text,
  created_at     timestamptz not null default now(),
  last_seen_at   timestamptz not null default now(),
  expires_at     timestamptz not null,                 -- absolute expiry
  idle_timeout_seconds int not null default 1800,
  revoked_at     timestamptz,
  revoke_reason  text
);
create index sessions_user_idx on iam.sessions(user_id) where revoked_at is null;
create index sessions_expiry_idx on iam.sessions(expires_at);

-- ---------------------------------------------------------------------
-- AUDIT
-- ---------------------------------------------------------------------
create table audit.audit_log (
  id           uuid primary key default gen_random_uuid(),
  occurred_at  timestamptz not null default now(),
  company_id   uuid,
  branch_id    uuid,
  user_id      uuid,
  session_id   uuid,
  device_id    uuid,
  node_id      uuid,
  action       text not null,                          -- e.g. 'auth.login', 'row.update', 'pos.order.void'
  entity_table text,
  entity_id    uuid,
  reason_code  text,
  reason_text  text,
  approved_by  uuid,
  old_data     jsonb,
  new_data     jsonb,
  ip_address   inet,
  metadata     jsonb not null default '{}'::jsonb
);
create index audit_company_time_idx on audit.audit_log(company_id, occurred_at desc);
create index audit_entity_idx on audit.audit_log(entity_table, entity_id);
create index audit_user_idx on audit.audit_log(user_id, occurred_at desc);
create index audit_action_idx on audit.audit_log(action);
create trigger audit_log_append_only before update or delete on audit.audit_log
  for each row execute function app.forbid_mutation();

-- row-level change audit for sensitive tables
create or replace function audit.capture_row_change() returns trigger language plpgsql security definer
set search_path = pg_catalog, public as $$
declare v_old jsonb; v_new jsonb; v_row jsonb;
begin
  if tg_op <> 'INSERT' then v_old := to_jsonb(old) - 'password_hash' - 'pin_hash' - 'token_hash'; end if;
  if tg_op <> 'DELETE' then v_new := to_jsonb(new) - 'password_hash' - 'pin_hash' - 'token_hash'; end if;
  v_row := coalesce(v_new, v_old);
  insert into audit.audit_log(company_id, branch_id, user_id, action, entity_table, entity_id, old_data, new_data, metadata)
  values (
    nullif(v_row->>'company_id','')::uuid,
    nullif(v_row->>'branch_id','')::uuid,
    app.current_user_id(),
    'row.' || lower(tg_op),
    tg_table_schema || '.' || tg_table_name,
    nullif(v_row->>'id','')::uuid,
    v_old, v_new,
    jsonb_build_object('reason_code', nullif(current_setting('app.reason_code', true), ''),
                       'reason_text', nullif(current_setting('app.reason_text', true), ''),
                       'request_id',  nullif(current_setting('app.request_id', true), ''))
  );
  return null;
end $$;

-- ---------------------------------------------------------------------
-- SYNCHRONIZATION INFRASTRUCTURE (engine implemented in Phase 9)
-- ---------------------------------------------------------------------
create table sync.nodes (                            -- cloud hub + one local server per branch
  id          uuid primary key default gen_random_uuid(),
  company_id  uuid references org.companies(id),
  branch_id   uuid references org.branches(id),
  node_type   text not null check (node_type in ('cloud','branch_server')),
  name        text not null,
  base_url    text,
  public_key  text,                                  -- mTLS / request signing
  last_seen_at timestamptz,
  status      text not null default 'active' check (status in ('active','inactive','revoked')),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  created_by uuid, updated_by uuid, row_version bigint not null default 1,
  check ((node_type = 'cloud' and branch_id is null) or (node_type = 'branch_server' and branch_id is not null))
);
create unique index nodes_branch_uq on sync.nodes(branch_id) where node_type = 'branch_server' and status = 'active';

-- identity of THIS database instance (exactly one row)
create table sync.local_node (
  singleton  boolean primary key default true check (singleton),
  node_id    uuid not null,
  node_type  text not null check (node_type in ('cloud','branch_server')),
  branch_id  uuid,
  created_at timestamptz not null default now()
);
create or replace function app.node_id() returns uuid language sql stable as $$ select node_id from sync.local_node $$;

create table sync.devices (                          -- POS terminals, KDS screens, waiter tablets, rider phones
  id            uuid primary key default gen_random_uuid(),
  company_id    uuid not null references org.companies(id),
  branch_id     uuid not null,
  code          citext not null,
  name          text not null,
  device_type   text not null check (device_type in ('pos_terminal','kds_screen','waiter_device','rider_device','kiosk','printer_bridge','back_office')),
  fingerprint   text,
  secret_hash   bytea,                               -- device credential (sha256); raw secret shown once
  registered_by uuid,
  approved_by   uuid,
  approved_at   timestamptz,
  last_seen_at  timestamptz,
  app_version   text,
  status        text not null default 'pending' check (status in ('pending','active','blocked','retired')),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  created_by uuid, updated_by uuid, row_version bigint not null default 1,
  foreign key (company_id, branch_id) references org.branches(company_id, id),
  unique (company_id, code)
);
create index devices_branch_idx on sync.devices(branch_id);
alter table iam.sessions add constraint sessions_device_fk foreign key (device_id) references sync.devices(id);

-- registry of replicated tables and who owns them
create table sync.tracked_tables (
  table_name  text primary key,                     -- schema.table
  ownership   text not null check (ownership in ('cloud','branch','shared')),
  -- cloud  = master data authored centrally, pushed down
  -- branch = operational records authored at branch, pushed up (append-only financial/inventory)
  -- shared = either side may edit (e.g. customers); conflicts detected by row_version
  conflict_policy text not null default 'reject' check (conflict_policy in ('reject','owner_wins','last_writer_wins','manual')),
  priority    int not null default 100,             -- apply order (masters first)
  created_at  timestamptz not null default now()
);

create table sync.outbox (
  seq           bigserial primary key,              -- local ordering
  event_id      uuid not null unique default gen_random_uuid(),  -- global idempotency key
  origin_node_id uuid,
  company_id    uuid,
  branch_id     uuid,
  table_name    text not null,
  row_id        uuid not null,
  operation     text not null check (operation in ('insert','update','delete')),
  row_version   bigint,
  payload       jsonb not null,
  created_at    timestamptz not null default now(),
  status        text not null default 'pending' check (status in ('pending','sent','acked','failed','dead')),
  attempts      int not null default 0,
  next_attempt_at timestamptz not null default now(),
  last_error    text,
  acked_at      timestamptz
);
create index outbox_pending_idx on sync.outbox(status, next_attempt_at) where status in ('pending','failed');
create index outbox_company_idx on sync.outbox(company_id, seq);

create table sync.inbox (
  event_id      uuid primary key,                   -- dedupe: same event never applied twice
  origin_node_id uuid not null,
  company_id    uuid,
  branch_id     uuid,
  table_name    text not null,
  row_id        uuid not null,
  operation     text not null check (operation in ('insert','update','delete')),
  row_version   bigint,
  payload       jsonb not null,
  received_at   timestamptz not null default now(),
  applied_at    timestamptz,
  status        text not null default 'received' check (status in ('received','applied','conflict','failed','skipped')),
  attempts      int not null default 0,
  last_error    text
);
create index inbox_status_idx on sync.inbox(status, received_at);

create table sync.checkpoints (                      -- high-water marks per peer & direction
  peer_node_id  uuid not null,
  direction     text not null check (direction in ('push','pull')),
  stream        text not null default 'default',
  last_seq      bigint not null default 0,
  last_event_id uuid,
  last_success_at timestamptz,
  last_error    text,
  updated_at    timestamptz not null default now(),
  primary key (peer_node_id, direction, stream)
);

create table sync.conflicts (
  id            uuid primary key default gen_random_uuid(),
  company_id    uuid,
  branch_id     uuid,
  event_id      uuid not null references sync.inbox(event_id),
  table_name    text not null,
  row_id        uuid not null,
  local_version bigint,
  remote_version bigint,
  local_data    jsonb,
  remote_data   jsonb,
  conflict_type text not null check (conflict_type in ('version_mismatch','ownership_violation','constraint_violation','missing_parent','immutable_record')),
  resolution    text check (resolution in ('kept_local','applied_remote','merged','discarded')),
  resolved_by   uuid,
  resolved_at   timestamptz,
  notes         text,
  status        text not null default 'open' check (status in ('open','resolved')),
  created_at    timestamptz not null default now()
);
create index conflicts_open_idx on sync.conflicts(company_id, status);

-- outbox capture: every change to a tracked table becomes an event in the same transaction
create or replace function sync.capture_change() returns trigger language plpgsql as $$
declare v_row jsonb;
begin
  if app.sync_applying() then return null; end if;   -- changes applied from inbox are not re-emitted
  v_row := case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end;
  insert into sync.outbox(origin_node_id, company_id, branch_id, table_name, row_id, operation, row_version, payload)
  values (app.node_id(),
          nullif(v_row->>'company_id','')::uuid,
          nullif(v_row->>'branch_id','')::uuid,
          tg_table_schema || '.' || tg_table_name,
          (v_row->>'id')::uuid,
          lower(tg_op),
          nullif(v_row->>'row_version','')::bigint,
          v_row);
  return null;
end $$;
